import{_ as e,o,c as r,a2 as a}from"./chunks/framework.CfwCq2QB.js";const c=JSON.parse('{"title":"FAQ 与故障排查","description":"","frontmatter":{},"headers":[],"relativePath":"faq/index.md","filePath":"faq/index.md"}'),i={name:"faq/index.md"};function l(s,t,n,d,h,p){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="faq-与故障排查" tabindex="-1">FAQ 与故障排查 <a class="header-anchor" href="#faq-与故障排查" aria-label="Permalink to &quot;FAQ 与故障排查&quot;">​</a></h1><h2 id="划词工具条不出现" tabindex="-1">划词工具条不出现？ <a class="header-anchor" href="#划词工具条不出现" aria-label="Permalink to &quot;划词工具条不出现？&quot;">​</a></h2><p><strong>现象</strong>：选中网页文字，工具条没有浮出来。</p><p><strong>原因</strong>：按网站停用了划词、全局关闭了划词、或只在输入框场景看不到网页类动作。</p><p><strong>步骤</strong>：</p><ol><li>打开弹窗「功能」页，看「划词工具条」开关：若显示「已在 xxx 停用」，打开即可</li><li>去设置页「划词 → 启用划词」确认全局开关是开的</li><li>在输入框里选中文字只会显示写作类动作（润色 / 纠错 / 正式及适用输入框的自定义动作），看不到翻译 / 解释是正常的</li><li>都正常还不行：刷新页面再选一次；安装扩展前就打开的页面需要刷新后内容脚本才注入</li></ol><h2 id="开了真实-ip-防护后-网页会议-语音通话连不上" tabindex="-1">开了真实 IP 防护后，网页会议 / 语音通话连不上？ <a class="header-anchor" href="#开了真实-ip-防护后-网页会议-语音通话连不上" aria-label="Permalink to &quot;开了真实 IP 防护后，网页会议 / 语音通话连不上？&quot;">​</a></h2><p><strong>现象</strong>：开启防护（尤其「隐藏真实 IP」级别）后，网页版会议、通话变慢或连不上。</p><p><strong>原因</strong>：这是防护的已知代价——网页的音视频连接只能经代理建立，代理不支持 UDP 时更明显。电脑上的会议客户端不受影响。</p><p><strong>步骤</strong>：</p><ol><li>设置页「网络 → 真实 IP 防护」，把级别先改回「不防护（浏览器默认）」，刷新网页验证</li><li>确认是防护导致后，按需换用「隐藏局域网地址」这类影响更小的级别（真实 IP 仍会暴露，自行权衡）</li><li>只在个别网站需要开会？可以临时切回「不防护」，开完会再改回来</li></ol><p>详见<a href="/dev-go-docs/features/ip-protection.html">真实 IP 防护</a>。</p><h2 id="firefox-里代理切换不可用" tabindex="-1">Firefox 里代理切换不可用？ <a class="header-anchor" href="#firefox-里代理切换不可用" aria-label="Permalink to &quot;Firefox 里代理切换不可用？&quot;">​</a></h2><p><strong>现象</strong>：Firefox 构建里切换网络模式没有效果。</p><p><strong>原因</strong>：DevGo 的代理控制基于 Chromium 的 <code>chrome.proxy</code> 设置接口，Firefox 的实现与配置格式不同，暂未适配。</p><p><strong>步骤</strong>：</p><ol><li>Firefox 下请使用系统代理或代理软件自身的分流</li><li>真实 IP 防护、CORS 调试等其他网络功能不受此影响</li><li>Firefox 的代理适配在计划中，可到 <a href="https://github.com/fedtop/DevGo/issues" target="_blank" rel="noreferrer">Issues</a> 关注进展</li></ol><h2 id="网页工具-webmcp-里什么都没有" tabindex="-1">网页工具（WebMCP）里什么都没有？ <a class="header-anchor" href="#网页工具-webmcp-里什么都没有" aria-label="Permalink to &quot;网页工具（WebMCP）里什么都没有？&quot;">​</a></h2><p><strong>现象</strong>：侧边栏「网页工具」页提示不支持、读取不到或没有工具。</p><p><strong>原因</strong>：WebMCP 是 Chrome 150+ 的实验功能，需要手动开启；且网页本身要通过 WebMCP 注册工具。</p><p><strong>步骤</strong>：</p><ol><li>确认 Chrome ≥ 150</li><li>打开 <code>chrome://flags</code>，搜索「WebMCP for testing」，启用后重启浏览器</li><li>普通网页本来就没有工具属正常；不确定时点「重新检测」</li></ol><p>详见<a href="/dev-go-docs/features/webmcp.html">网页工具（WebMCP）</a>。</p><h2 id="ai-报-401-404-429-怎么办" tabindex="-1">AI 报 401 / 404 / 429 怎么办？ <a class="header-anchor" href="#ai-报-401-404-429-怎么办" aria-label="Permalink to &quot;AI 报 401 / 404 / 429 怎么办？&quot;">​</a></h2><p><strong>现象</strong>：划词 AI 动作、侧边栏助手或 AI 翻译报错。</p><p><strong>原因与步骤</strong>（按错误码）：</p><table tabindex="0"><thead><tr><th>报错</th><th>含义</th><th>处理</th></tr></thead><tbody><tr><td>鉴权失败 / 401</td><td>API Key 无效，或不属于当前接口地址的服务</td><td>核对 Key；刚切换服务预设的，确认 Key 来自该服务</td></tr><tr><td>404</td><td>接口地址或模型名不存在</td><td>Base URL 填到 <code>/v1</code> 即可（会自动补全）；模型名对照服务商文档</td></tr><tr><td>429</td><td>请求过于频繁或额度不足</td><td>稍后重试；检查账户额度与并发限制</td></tr><tr><td>连接失败 / 超时</td><td>网络不通或地址写错</td><td>检查网络（是否需要代理）；用「测试连接」验证</td></tr></tbody></table><p>配置入口：设置页「<a href="/dev-go-docs/settings/models.html">AI 模型</a>」。</p><h2 id="整页翻译没有译文" tabindex="-1">整页翻译没有译文？ <a class="header-anchor" href="#整页翻译没有译文" aria-label="Permalink to &quot;整页翻译没有译文？&quot;">​</a></h2><p><strong>现象</strong>：点了「翻译当前页面」，页面没变化或部分段落没有译文。</p><p><strong>步骤</strong>：</p><ol><li>目标语言设为「自动」时，中文页面会译成英文、其余译成简体中文——翻译成「同一种语言」时看起来像没生效，换明确的目标语言试试</li><li>引擎不可达：Google 引擎需要代理；微软引擎免翻墙。弹窗里切换引擎再试</li><li>选了「AI 大模型」但未配置 / Key 失效：弹窗会提示「还没有配置翻译模型」，去配置或先切回微软</li><li>部分段落失败：段落后面有 ↻ 可单独重试；仍失败换引擎</li><li>浏览器内置页、扩展商店不支持翻译，属正常限制</li></ol><h2 id="扩展更新后被浏览器停用了" tabindex="-1">扩展更新后被浏览器停用了？ <a class="header-anchor" href="#扩展更新后被浏览器停用了" aria-label="Permalink to &quot;扩展更新后被浏览器停用了？&quot;">​</a></h2><p><strong>现象</strong>：更新 DevGo 后浏览器提示扩展被停用 / 需要重新确认权限。</p><p><strong>原因</strong>：浏览器对新旧版本<strong>权限差异</strong>的处理，DevGo 的 <code>privacy</code> 是可选权限，仅在你开启真实 IP 防护时才申请，不会因它触发停用；若未来版本新增普通权限，浏览器按规则要求你重新确认。</p><p><strong>步骤</strong>：在 <code>chrome://extensions</code> 的 DevGo 卡片上按提示重新启用即可，配置与数据不受影响。</p><h2 id="如何回到默认设置" tabindex="-1">如何回到默认设置？ <a class="header-anchor" href="#如何回到默认设置" aria-label="Permalink to &quot;如何回到默认设置？&quot;">​</a></h2><p><strong>现象</strong>：想清掉所有自定义配置，回到全新状态。</p><p><strong>步骤</strong>：</p><ol><li>没有一键重置入口。单个功能在对应设置页逐项改回即可（如划词动作逐个删除、停用列表逐个移除）</li><li>想彻底重来：移除扩展后重新安装，本机数据（划词动作、代理配置、停用列表、API Key）会全部清空，恢复默认</li><li>反向操作前建议先「导出配置」留底，配错了一键导入即可恢复</li></ol><h2 id="在哪提功能建议-报-bug" tabindex="-1">在哪提功能建议 / 报 bug？ <a class="header-anchor" href="#在哪提功能建议-报-bug" aria-label="Permalink to &quot;在哪提功能建议 / 报 bug？&quot;">​</a></h2><p><strong>步骤</strong>：到 <a href="https://github.com/fedtop/DevGo/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 提交。报 bug 时带上：浏览器与版本、DevGo 版本（设置页或 <code>chrome://extensions</code> 可查）、复现步骤和报错截图，能显著加快定位。</p>',42)])])}const f=e(i,[["render",l]]);export{c as __pageData,f as default};
